"use strict";(self.webpackChunknotes=self.webpackChunknotes||[]).push([["192"],{1900(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"dsaSidebar":[{"type":"category","label":"Dynamic Programming","collapsible":true,"collapsed":false,"items":[{"type":"category","label":"Form 1","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form1/problem1","label":"Iterative Techniques","docId":"DSA/DynamicProgramming/Form1/problem1","unlisted":false},{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form1/Knapsack","label":"Knapsack","docId":"DSA/DynamicProgramming/Form1/Knapsack","unlisted":false}],"href":"/Notes/DSA/DynamicProgramming/Form1/"},{"type":"category","label":"Form 2","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form2/Substrings","label":"Distinct Substrings","docId":"DSA/DynamicProgramming/Form2/Substrings","unlisted":false}],"href":"/Notes/DSA/DynamicProgramming/Form2/"},{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form3/","label":"Form 3","docId":"DSA/DynamicProgramming/Form3/index","unlisted":false},{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form4/","label":"Form 4","docId":"DSA/DynamicProgramming/Form4/index","unlisted":false},{"type":"link","href":"/Notes/DSA/DynamicProgramming/Form5/","label":"Form 5","docId":"DSA/DynamicProgramming/Form5/index","unlisted":false}],"href":"/Notes/DSA/DynamicProgramming/"}]},"docs":{"DSA/DynamicProgramming/Form1/index":{"id":"DSA/DynamicProgramming/Form1/index","title":"Form 1","description":"When the states of a recursion are made by making choices as to take/not take an element of the available data structure and try to optimize/count a related value, it most probably than not can be solved with Form 1. It can be noted that if the problem statement, say f(0...N) is what is to be computed, the DP definition in this case can be made using f(i...N), along with extra constraints like rec(i,...) from the question itself. It\'s like saying if the problem can be solved i...N it can also be solved for 0...N. This gets clearer as we look at the example below.","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form1/Knapsack":{"id":"DSA/DynamicProgramming/Form1/Knapsack","title":"Knapsack","description":"Given a set of items, each with a weight and a value, determine which items to include in the collection so that the total weight is less than or equal to a given limit and the total value is as large as possible.","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form1/problem1":{"id":"DSA/DynamicProgramming/Form1/problem1","title":"Iterative Techniques","description":"Partition Equal Sum Subset Link","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form2/index":{"id":"DSA/DynamicProgramming/Form2/index","title":"Form 2","description":"When the dp subproblem gets reduced to finding a solution for dp[0...i], to be able to solve for dp[0...n] it can be solved with form 2. Note that dp[0...i] might not be the answer to the problem but might be something that\'ll be needed to arrive at the final answer. Now it\'s not to say that it can\'t be solved with any other form, but it\'s easier to solve it considering the subproblems definition to be from [0...i].","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form2/Substrings":{"id":"DSA/DynamicProgramming/Form2/Substrings","title":"Distinct Substrings","description":"Given a string s = \\"abaab\\", find the total number of distinct substrings.","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form3/index":{"id":"DSA/DynamicProgramming/Form3/index","title":"Form 3","description":"Problems that involve considering multiple sequences can be solved using Form 3. Note that the subproblem definition may differ from the actual problem to be solved. The DP state looks something like (infoseq1, infoseq2, extra constraints...). Consider the question below:","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form4/index":{"id":"DSA/DynamicProgramming/Form4/index","title":"Form 4","description":"Whenever you have a problem that needs to optimize merging or range deletion where the result of merging also feeds into further merges, it can be solved using Form 4. The states of the DP are the extreme ends of the range decided by the problem, along with other relevant constraints","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/Form5/index":{"id":"DSA/DynamicProgramming/Form5/index","title":"Form 5","description":"Certain problems involve games played optimally between 2 or more players. The state here is the state of the game itself. A state is a winning state if and only if all states reachable from it are losing states. A losing state is one where at least one of the reachable next states is a winning state \u2014 meaning the opponent can always escape. Consider the problem:","sidebar":"dsaSidebar"},"DSA/DynamicProgramming/index":{"id":"DSA/DynamicProgramming/index","title":"Dynamic Programming","description":"Dynamic Programming essentially is an optimization method used to convert a recursion tree into a Directed Acyclic Graph, thus reducing the recomputation overhead for same nodes. For example the code","sidebar":"dsaSidebar"},"index":{"id":"index","title":"Welcome","description":"Welcome to my notes."},"intro":{"id":"intro","title":"Tutorial Intro","description":"Let\'s discover Docusaurus in less than 5 minutes."},"tutorial-basics/congratulations":{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template."},"tutorial-basics/create-a-blog-post":{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed..."},"tutorial-basics/create-a-document":{"id":"tutorial-basics/create-a-document","title":"Create a Document","description":"Documents are groups of pages connected through:"},"tutorial-basics/create-a-page":{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:"},"tutorial-basics/deploy-your-site":{"id":"tutorial-basics/deploy-your-site","title":"Deploy your site","description":"Docusaurus is a static-site-generator (also called Jamstack)."},"tutorial-basics/markdown-features":{"id":"tutorial-basics/markdown-features","title":"Markdown Features","description":"Docusaurus supports Markdown and a few additional features."},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."}}}}')}}]);